UPDATE public.posts
SET 
  excerpt = CASE 
    WHEN title LIKE '%Analog Revival%' THEN 'Exploring the tactical feel of vintage gear and why analog is making a massive comeback.'
    WHEN title LIKE '%Defying Gravity%' THEN 'Mental grit, pushing physical boundaries, and defying gravity on the mountain.'
    WHEN title LIKE '%Minimalist Workspaces%' THEN 'How raw materials and minimalist aesthetics are shaping the new definition of focus.'
    WHEN title LIKE '%Reading a City%' THEN 'Navigating the hidden streets of mega-cities and the culture of urban exploration.'
    WHEN title LIKE '%Brutalist Typography%' THEN 'How grids, whitespace, and brutalist layouts are redefining modern visual communication.'
    WHEN title LIKE '%Nature''s Palette%' THEN 'A deep dive into preserving natural elements and the romantic allure of earth tones.'
    WHEN title LIKE '%Virtual Reality%' THEN 'The beautiful intersection of art and science, and how tech is rewiring education.'
    WHEN title LIKE '%Moment in the Sun%' THEN 'Breaking the monotone: expressive choices and the timeless stories written in waiting.'
    WHEN title LIKE '%Resilient Architecture%' THEN 'Designing for the future: climate-resilient structures and sustainable materials.'
    WHEN title LIKE '%Vertical Ice%' THEN 'Mental fortitude and pushing limits in the dangerous world of crevasse climbing.'
    WHEN title LIKE '%Swiss Typography%' THEN 'Before the 1950s, graphic design was largely decorative. Then the grid changed everything.'
    WHEN title LIKE '%Mastering Natural Light%' THEN 'Capturing fleeting moments: the art of working with natural sunlight in photography.'
    WHEN title LIKE '%Modern Building Facades%' THEN 'Raw concrete gets a bad reputation, but it is actually a material of immense warmth.'
    WHEN title LIKE '%Chasing the Horizon%' THEN 'A photographic journey capturing surreal moments and vast landscapes.'
    WHEN title LIKE '%Beyond the Piste%' THEN 'Backcountry survival skills and the spiritual experience of untouched powder.'
    WHEN title LIKE '%Concrete Oasis%' THEN 'Designing urban villas that serve as expansive, isolated retreats in dense cities.'
    WHEN title LIKE '%Artificial Intelligence%' THEN 'Inside the war room: the high-stakes culture of modern tech and artificial intelligence.'
    WHEN title LIKE '%Serenity in Blue%' THEN 'The psychology of comfort, coastal living, and finding peace in the modern world.'
    WHEN title LIKE '%Symphony in Space%' THEN 'The unseen engineer: meticulously balancing frequencies and acoustic architecture.'
    WHEN title LIKE '%Neon Nights%' THEN 'Tokyo at night is a cyberpunk dream made real. The glow of neon signs is intoxicating.'
    WHEN title LIKE '%Solitude at Elevation%' THEN 'Extreme cold changes the way we think. Finding absolute solitude at 12,000 feet.'
    ELSE 'An in-depth exploration of the themes, techniques, and stories behind this fascinating subject.'
  END,

  content = CASE
    WHEN title LIKE '%Analog Revival%' THEN $$<p class="dropcap">The crackle of analog gear is a feeling that digital perfection simply cannot replicate.</p><p>In an era where everything is available at the tap of a screen, we are seeing a massive resurgence in physical, tactical media.</p><blockquote>"Analog has a soul. It’s imperfect, it’s warm, and it’s deeply human."</blockquote><h3>The Tactile Experience</h3><ul><li><strong>Warmth:</strong> The distinct, rich mechanical response.</li><li><strong>Intentionality:</strong> Committing to the physical process.</li><li><strong>Art:</strong> Experiencing the raw format in full scale.</li></ul>$$
    
    WHEN title LIKE '%Defying Gravity%' THEN $$<p class="dropcap">Adrenaline is a powerful drug, but it is mental fortitude that truly separates the casual enthusiast from the dedicated extreme athlete.</p><p>Pushing past physical limits requires tapping into the flow state—a psychological space where time slows down and instinct takes over.</p><blockquote>"You don't conquer the mountain. You conquer yourself."</blockquote><h3>Mental Fortitude</h3><ul><li><strong>Focus:</strong> Blocking out fear and finding absolute clarity.</li><li><strong>Resilience:</strong> The ability to bounce back from failure.</li><li><strong>Preparation:</strong> The hours of unseen labor.</li></ul>$$
    
    WHEN title LIKE '%Minimalist Workspaces%' THEN $$<p class="dropcap">Design is not just what it looks like and feels like; design is how it works.</p><p>Modern workspaces are undergoing a radical transformation, moving away from cluttered desks toward raw, resilient, and honest environments.</p><blockquote>"Good design is as little design as possible."</blockquote><h3>Material Honesty</h3><ul><li><strong>Whitespace:</strong> Giving your mind room to breathe.</li><li><strong>Function:</strong> Stripping away the unnecessary.</li><li><strong>Light:</strong> Using natural shadows as a design element.</li></ul>$$
    
    WHEN title LIKE '%Reading a City%' THEN $$<p class="dropcap">The glow of neon against wet asphalt is the defining aesthetic of the modern mega-city.</p><p>Urban exploration reveals a layered world. Beneath the gleaming corporate skyscrapers lies a labyrinth of tiny alleyways and hidden subcultures.</p><blockquote>"The city speaks, you just have to learn the language."</blockquote><h3>Urban Exploration</h3><ul><li><strong>Scale:</strong> Feeling small in a massive metropolis.</li><li><strong>Contrast:</strong> Ancient history sitting next to futuristic tech.</li><li><strong>Nightlife:</strong> The city truly wakes up when the sun goes down.</li></ul>$$
    
    WHEN title LIKE '%Brutalist Typography%' THEN $$<p class="dropcap">Graphic design is experiencing a brutalist renaissance. The clean, hyper-minimalist styles are being torn apart.</p><p>Digital collage allows artists to merge vintage elements with sharp, modern vectors. It is a visual representation of our chaotic modern lives.</p><blockquote>"You have to destroy the grid before you can truly understand it."</blockquote><h3>Collage Techniques</h3><ul><li><strong>Layering:</strong> Building depth through contrasting textures.</li><li><strong>Color Theory:</strong> Using neon accents against halftone photos.</li><li><strong>Typography:</strong> Treating letters as graphical shapes.</li></ul>$$
    
    WHEN title LIKE '%Nature''s Palette%' THEN $$<p class="dropcap">Humanity and nature are inextricably linked, yet we often separate them in our designs.</p><p>By bringing elements of the wild into our living spaces and art, we blur the lines between the civilized and the untamed.</p><blockquote>"We are not observers of nature; we are participants in it."</blockquote><h3>Earth Tones</h3><ul><li><strong>Harmony:</strong> Making spaces feel completely natural.</li><li><strong>Spontaneity:</strong> Embracing the chaos of organic shapes.</li><li><strong>Lighting:</strong> Keeping the mood warm and unforced.</li></ul>$$
    
    WHEN title LIKE '%Virtual Reality%' THEN $$<p class="dropcap">The human brain is a galaxy of synapses, constantly forming and pruning connections.</p><p>With the advent of immersive tech, scientists are unlocking secrets of neuroplasticity—the brain's remarkable ability to completely rewire itself in response to learning.</p><blockquote>"We are capable of rewiring our own destiny."</blockquote><h3>Neuroplasticity Explained</h3><ul><li><strong>Learning:</strong> How new skills thicken the cerebral cortex.</li><li><strong>Immersion:</strong> Virtual environments tricking the senses.</li><li><strong>Focus:</strong> Altering physical brain structures through engagement.</li></ul>$$
    
    WHEN title LIKE '%Moment in the Sun%' THEN $$<p class="dropcap">Clocks measure hours, but experiences measure life. Our society is obsessed with rushing, yet true character is carved by waiting.</p><p>Taking a moment to pause provides a mirror into our own minds. Aging and waiting are not declines; they are accumulations of wisdom.</p><blockquote>"Time is a sculptor, and we are its masterpiece."</blockquote><h3>Embracing Time</h3><ul><li><strong>Wisdom:</strong> The quiet confidence of patience.</li><li><strong>Stillness:</strong> True peace solidifies when we stop moving.</li><li><strong>Legacy:</strong> What we leave behind when the clocks stop.</li></ul>$$
    
    WHEN title LIKE '%Resilient Architecture%' THEN $$<p class="dropcap">Climate change demands new blueprints. The structures we build today must be prepared for the extreme weather of tomorrow.</p><p>Resilient architecture focuses on passive cooling, flood-resistant foundations, and sustainable materials. It is a shift from fighting nature to working alongside it.</p><blockquote>"Build for the storm, design for the calm."</blockquote><h3>Sustainable Materials</h3><ul><li><strong>Locality:</strong> Sourcing stone and timber locally.</li><li><strong>Insulation:</strong> Reducing the need for active heating.</li><li><strong>Adaptability:</strong> Buildings that can change function.</li></ul>$$
    
    WHEN title LIKE '%Vertical Ice%' THEN $$<p class="dropcap">Extreme cold changes the way we think. Fingers go numb, and equipment freezes.</p><p>Yet, the results are unparalleled. The clarity of the air and the dramatic contrast of ice against rock creates an environment that requires a specific kind of madness to conquer.</p><blockquote>"Ice is a harsh mirror, reflecting only the brave."</blockquote><h3>Extreme Gear</h3><ul><li><strong>Insulation:</strong> Keeping warm inside your jacket.</li><li><strong>Grip:</strong> Dealing with condensation and frost.</li><li><strong>Exposure:</strong> Surviving in sub-zero environments.</li></ul>$$
    
    WHEN title LIKE '%Swiss Typography%' THEN $$<p class="dropcap">The grid changed everything. Before the Swiss Style emerged in the 1950s, graphic design was largely decorative.</p><p>By enforcing strict mathematical grids and utilizing sans-serif typefaces like Helvetica, designers brought order to chaos. This philosophy still underpins all modern UI/UX design today.</p><blockquote>"Order out of chaos is the ultimate goal of the designer."</blockquote><h3>Typography Fundamentals</h3><ul><li><strong>Hierarchy:</strong> Guiding the eye through size and weight.</li><li><strong>Alignment:</strong> The invisible lines that hold a layout together.</li><li><strong>Clarity:</strong> Prioritizing readability over decoration.</li></ul>$$
    
    WHEN title LIKE '%Mastering Natural Light%' THEN $$<p class="dropcap">Sunlight is the ultimate modifier. No artificial light can replicate the wrap and quality of a sun obscured by thick clouds.</p><p>Mastering natural light means giving up control. You must adapt to what the sky gives you, moving your subject and finding the pockets of illumination that make a scene sing.</p><blockquote>"Chase the light, and the shadows will take care of themselves."</blockquote><h3>Lighting Techniques</h3><ul><li><strong>Golden Hour:</strong> The soft, warm light just after sunrise.</li><li><strong>Blue Hour:</strong> The moody, cool tones just after sunset.</li><li><strong>Harsh Sun:</strong> Using midday light for high contrast.</li></ul>$$
    
    WHEN title LIKE '%Modern Building Facades%' THEN $$<p class="dropcap">Raw concrete gets a bad reputation. Often associated with cold, oppressive structures, it is actually a material of immense warmth when used correctly.</p><p>Modern urban facades are embracing brutalism by pairing raw concrete walls with lush greenery. The contrast creates a sanctuary in the middle of a noisy city.</p><blockquote>"Minimalism is not empty; it is fiercely focused."</blockquote><h3>Brutalist Elements</h3><ul><li><strong>Texture:</strong> Highlighting wooden formwork imprints.</li><li><strong>Light:</strong> Using harsh angles to cast dramatic shadows.</li><li><strong>Integration:</strong> Blurring the line between inside and out.</li></ul>$$
    
    WHEN title LIKE '%Chasing the Horizon%' THEN $$<p class="dropcap">A photograph is a pause button on life. It isolates a fraction of a second, preserving a fleeting emotion or landscape.</p><p>The golden hour provides a quality of light that transforms the mundane into the magical. But mastering landscapes requires intense observation and timing.</p><blockquote>"You don't take a photograph, you make it."</blockquote><h3>Chasing the Light</h3><ul><li><strong>Patience:</strong> Waiting hours for perfect alignment.</li><li><strong>Composition:</strong> Using leading lines to guide the eye.</li><li><strong>Storytelling:</strong> Capturing the unspoken narrative.</li></ul>$$
    
    WHEN title LIKE '%Beyond the Piste%' THEN $$<p class="dropcap">Dropping into a pristine, untouched bowl of powder at 12,000 feet is a spiritual experience.</p><p>High-altitude sports require backcountry survival skills just as much as athletic ability. You are entirely at the mercy of the elements.</p><blockquote>"The mountain dictates the terms; we just ride them."</blockquote><h3>Backcountry Gear</h3><ul><li><strong>Splitboards:</strong> Hiking up before riding down.</li><li><strong>Beacons:</strong> Essential avalanche safety equipment.</li><li><strong>Layering:</strong> Managing sweat in sub-zero temps.</li></ul>$$
    
    WHEN title LIKE '%Concrete Oasis%' THEN $$<p class="dropcap">The modern urban villa is a paradox. It seeks to create an expansive, isolated retreat within the densest cities on earth.</p><p>By utilizing inward-facing courtyards and massive concrete privacy walls, architects are building introverted homes. They hide their beauty from the street.</p><blockquote>"True luxury in the modern world is absolute privacy."</blockquote><h3>Introverted Architecture</h3><ul><li><strong>Courtyards:</strong> Bringing the outdoors into the center.</li><li><strong>Acoustics:</strong> Baffling city noise with heavy masonry.</li><li><strong>Lighting:</strong> Skylights that wash walls without sacrificing privacy.</li></ul>$$
    
    WHEN title LIKE '%Artificial Intelligence%' THEN $$<p class="dropcap">Inside the tech war room, sleep is a luxury and coffee is a food group. The stakes are impossibly high.</p><p>Tech culture glorifies the grind. A small team of engineers can disrupt billion-dollar industries. The aesthetic of AI is a mix of chaotic code and pristine design.</p><blockquote>"Move fast, break things, and try not to break yourself."</blockquote><h3>Tech Culture</h3><ul><li><strong>Iteration:</strong> Shipping imperfect products just to get feedback.</li><li><strong>Funding:</strong> The constant stress of the next venture capital round.</li><li><strong>Camaraderie:</strong> The intense bond forged in the trenches.</li></ul>$$
    
    WHEN title LIKE '%Serenity in Blue%' THEN $$<p class="dropcap">Sometimes, a moment of deep comfort is exactly what the soul needs. We can't subsist on stress and hustle alone.</p><p>The psychology of serenity is deeply rooted in our evolutionary history. Coastal living and blue tones trigger a literal chemical blanket of peace in the brain.</p><blockquote>"Peace is a warm hug from the inside out."</blockquote><h3>Comfort Psychology</h3><ul><li><strong>Satiety:</strong> The physical feeling of fullness bringing peace.</li><li><strong>Tradition:</strong> Returning to the water's edge.</li><li><strong>Guilt-Free:</strong> Learning to enjoy life without hustle culture.</li></ul>$$
    
    WHEN title LIKE '%Symphony in Space%' THEN $$<p class="dropcap">Behind every great acoustic space is an unseen engineer meticulously balancing frequencies.</p><p>Acoustic architecture is an invisible art form. When done correctly, the listener never notices the structural tweaks or the subtle reverb tails. They just feel the sound.</p><blockquote>"A good room doesn't fix a bad song, but a bad room can ruin a great one."</blockquote><h3>Acoustic Environments</h3><ul><li><strong>Acoustics:</strong> Treating the room to remove reflections.</li><li><strong>Geometry:</strong> The debate between different ceiling structures.</li><li><strong>Patience:</strong> Creating the perfect listening space.</li></ul>$$
    
    WHEN title LIKE '%Neon Nights%' THEN $$<p class="dropcap">Cyberpunk cities at night are a dream made real. The glow of neon signs reflecting off wet pavement creates an intoxicating atmosphere.</p><p>Urban exploration reveals a layered world. Beneath the gleaming corporate skyscrapers lies a labyrinth of subcultures.</p><blockquote>"The city speaks in neon, you just have to learn the language."</blockquote><h3>Urban Exploration</h3><ul><li><strong>Scale:</strong> Feeling small in a city of 37 million people.</li><li><strong>Contrast:</strong> Ancient shrines next to futuristic arcades.</li><li><strong>Nightlife:</strong> The city truly wakes up when the sun goes down.</li></ul>$$
    
    WHEN title LIKE '%Solitude at Elevation%' THEN $$<p class="dropcap">Who says extreme heights are a young person's game? Gravity treats everyone equally.</p><p>We are seeing a surge in athletes tackling absolute solitude. With improved understanding of the human body, altitude is becoming an arena of intense spiritual achievement.</p><blockquote>"The mountain doesn't ask for your ID before you climb."</blockquote><h3>High-Altitude Athletics</h3><ul><li><strong>Mobility:</strong> Prioritizing flexibility over raw strength.</li><li><strong>Pacing:</strong> Knowing when to push and when to rest.</li><li><strong>Community:</strong> Finding peace above the clouds.</li></ul>$$
    
    ELSE $$<p class="dropcap">Every great movement begins with a shift in perspective.</p><p>In recent years, there has been a noticeable shift back towards authenticity. Audiences are craving something real.</p><blockquote>"Perfection is finally dead. We are entering the era of beautiful flaws."</blockquote><h3>The Philosophy of Restraint</h3><ul><li><strong>Honesty:</strong> Letting materials speak for themselves.</li><li><strong>Imperfection:</strong> Embracing natural wear and tear.</li><li><strong>Focus:</strong> Stripping away the unnecessary.</li></ul>$$
  END;
